function TelegramImage({url,alt,refreshSeconds=0}:{url:string,alt:string,refreshSeconds?:number}){
 const[src,setSrc]=useState('');const[error,setError]=useState('');
 useEffect(()=>{let cancelled=false;let objectUrl='';const load=async()=>{try{const response=await fetch(`${url}${url.includes('?')?'&':'?'}t=${Date.now()}`,{headers:apiAuthHeaders(),cache:'no-store'});if(!response.ok)throw new Error(response.status===404?'Кадр ещё не получен':'Кадр недоступен');const next=URL.createObjectURL(await response.blob());if(cancelled){URL.revokeObjectURL(next);return}if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=next;setSrc(next);setError('')}catch(e){if(!cancelled)setError(e instanceof Error?e.message:'Кадр недоступен')}};void load();const timer=refreshSeconds?window.setInterval(load,refreshSeconds*1000):0;return()=>{cancelled=true;if(timer)clearInterval(timer);if(objectUrl)URL.revokeObjectURL(objectUrl)}},[url,refreshSeconds]);
 return src?<img className="tg-live-image" src={src} alt={alt}/>:<div className="tg-image-empty"><Camera size={20}/><span>{error||'Получаю кадр…'}</span></div>
}
type TelegramReviewStatus='pending'|'accepted'|'rejected';
type TelegramToast={message:string,tone:'ok'|'warn'|'error'};
type CameraDiagnostic={camera_id:string,name:string,reachable:boolean,status:string,latency_ms:number|null,message:string,camera_status?:string,telemetry_age_seconds?:number|null,last_error?:string,snapshot?:string,snapshot_age_seconds?:number|null};

const telegramReviewStatus=(event:Event):TelegramReviewStatus=>event.review_status==='accepted'||event.review_status==='rejected'||event.review_status==='pending'?event.review_status:(event.acknowledged?'accepted':'pending');
const telegramAge=(seconds:number|null|undefined)=>seconds===null||seconds===undefined?'нет кадра':seconds<5?'только что':seconds<60?`${seconds} сек назад`:`${Math.floor(seconds/60)} мин назад`;
const telegramHaptic=(kind:'light'|'success'|'warning'|'error'='light')=>{try{const feedback=(window as any).Telegram?.WebApp?.HapticFeedback;if(!feedback)return;if(kind==='light')feedback.impactOccurred?.('light');else feedback.notificationOccurred?.(kind)}catch{}};
const telegramConfirm=(message:string)=>new Promise<boolean>(resolve=>{const tg=(window as any).Telegram?.WebApp;if(typeof tg?.showConfirm==='function'){tg.showConfirm(message,(accepted:boolean)=>resolve(Boolean(accepted)));return}resolve(window.confirm(message))});

function TelegramTrend({data,compact=false}:{data:{label:string,value:number}[],compact?:boolean}){
 const max=Math.max(...data.map(item=>item.value),1);const labelEvery=Math.max(1,Math.ceil(data.length/(compact?6:7)));
 if(!data.length)return <div className="tg-chart-empty">Данных за выбранный период пока нет</div>;
 return <div className={`tg-trend ${compact?'compact':''}`} role="img" aria-label="Динамика событий"><div className="tg-trend-bars">{data.map((item,index)=><div className="tg-trend-item" key={`${item.label}-${index}`} title={`${item.label}: ${item.value}`}><i style={{height:`${item.value?Math.max(8,item.value/max*100):3}%`}}/><small>{index%labelEvery===0?item.label:''}</small></div>)}</div></div>
}

function TelegramDonut({items,label,value}:{items:{id:string,label:string,value:number}[],label:string,value?:number}){
 const visible=items.filter(item=>item.value>0);const total=Math.max(visible.reduce((sum,item)=>sum+item.value,0),1);const colors=['#74c58b','#7daeff','#f0b85c','#ef746b','#a98cff'];let cursor=0;
 const stops=visible.map((item,index)=>{const next=cursor+item.value/total*100;const stop=`${colors[index%colors.length]} ${cursor}% ${next}%`;cursor=next;return stop});
 return <div className="tg-donut-wrap"><div className="tg-donut" style={{background:stops.length?`conic-gradient(${stops.join(',')})`:'#e8eeea'}}><div><b>{value??visible.reduce((sum,item)=>sum+item.value,0)}</b><small>{label}</small></div></div><div className="tg-donut-legend">{visible.map((item,index)=><span key={item.id}><i style={{background:colors[index%colors.length]}}/><b>{item.value}</b><small>{item.label}</small></span>)}</div></div>
}

function TelegramBars({items,limit=5}:{items:{id:string,label:string,value:number}[],limit?:number}){
 const visible=items.filter(item=>item.value>0).slice(0,limit);const max=Math.max(...visible.map(item=>item.value),1);
 if(!visible.length)return <div className="tg-chart-empty">Пока нет событий</div>;
 return <div className="tg-bars">{visible.map((item,index)=><div className="tg-bar-row" key={item.id} data-tone={index%5}><span><b>{item.label}</b><small>{item.value}</small></span><i><em style={{width:`${Math.max(8,item.value/max*100)}%`}}/></i></div>)}</div>
}

function TelegramGauge({label,value,tone='green'}:{label:string,value:number|null|undefined,tone?:'green'|'blue'|'amber'|'red'}){
 const safe=value===null||value===undefined?null:Math.max(0,Math.min(100,value));
 return <div className={`tg-gauge ${tone}`}><span><b>{safe===null?'—':`${Math.round(safe)}%`}</b><small>{label}</small></span><i><em style={{width:`${safe??0}%`}}/></i></div>
}

function TelegramMini(){
 type TelegramView='Главная'|'Аналитика'|'Камеры'|'События'|'Модели'|'Ещё';
 type TelegramEventFilter='all'|'pending'|'critical'|'accepted'|'rejected';
 type TelegramCameraFilter='all'|'online'|'attention';
 const[d,setD]=useState<Dashboard|null>(null);const[events,setEvents]=useState<Event[]>([]);const[cams,setCams]=useState<Cam[]>([]);const[models,setModels]=useState<Model[]>([]);const[health,setHealth]=useState<SystemHealth|null>(null);const[session,setSession]=useState<TelegramSession|null>(null);const[analytics,setAnalytics]=useState<Analytics|null>(null);const[error,setError]=useState('');const[view,setView]=useState<TelegramView>('Главная');const[loading,setLoading]=useState(true);const[busy,setBusy]=useState('');const[selectedCamera,setSelectedCamera]=useState<Cam|null>(null);const[selectedEvent,setSelectedEvent]=useState<Event|null>(null);const[analyticsHours,setAnalyticsHours]=useState<24|168|720>(24);const[eventFilter,setEventFilter]=useState<TelegramEventFilter>('all');const[cameraFilter,setCameraFilter]=useState<TelegramCameraFilter>('all');const[selectionMode,setSelectionMode]=useState(false);const[selectedEventIds,setSelectedEventIds]=useState<number[]>([]);const[diagnostics,setDiagnostics]=useState<Record<string,CameraDiagnostic>>({});const[toast,setToast]=useState<TelegramToast|null>(null);const toastTimer=useRef<number|undefined>(undefined);
 const notify=(message:string,tone:TelegramToast['tone']='ok')=>{setToast({message,tone});if(toastTimer.current)window.clearTimeout(toastTimer.current);toastTimer.current=window.setTimeout(()=>setToast(null),3200)};
 const load=async()=>{setLoading(true);setError('');try{const[a,b,c,m,h,identity,overview]=await Promise.all([api<Dashboard>('/api/dashboard'),api<Event[]>('/api/events?limit=100'),api<Cam[]>('/api/cameras'),api<Model[]>('/api/models'),api<SystemHealth>('/api/system-health'),api<TelegramSession>('/api/session'),api<Analytics>(`/api/analytics/overview?hours=${analyticsHours}&bucket=auto`)]);setD(a);setEvents(b);setCams(c);setModels(m);setHealth(h);setSession(identity);setAnalytics(overview)}catch(e){setError(e instanceof Error?e.message:'Сервис недоступен')}finally{setLoading(false)}};
 useEffect(()=>{let timer=0;let disposed=false;void loadTelegramSdk().then(()=>{if(disposed)return;const tg=(window as any).Telegram?.WebApp;tg?.ready();tg?.expand();try{tg?.setHeaderColor?.('#0c1510');tg?.setBackgroundColor?.('#0c1510');tg?.setBottomBarColor?.('#0c1510')}catch{};void load();timer=window.setInterval(()=>void load(),12000)});return()=>{disposed=true;if(timer)clearInterval(timer)}},[analyticsHours]);
 useEffect(()=>{const root=document.documentElement;const previousTheme=root.dataset.theme;const previousColorScheme=root.style.colorScheme;root.dataset.theme='dark';root.style.colorScheme='dark';return()=>{if(previousTheme)root.dataset.theme=previousTheme;else delete root.dataset.theme;root.style.colorScheme=previousColorScheme}},[]);
 useEffect(()=>()=>{if(toastTimer.current)window.clearTimeout(toastTimer.current)},[]);
 const role=session?.role||'local';const canOperate=role==='operator'||role==='admin'||role==='api_key';const canAdmin=role==='admin'||role==='api_key';const canReport=canOperate||role==='local';const activeModel=models.find(model=>model.active);const worker=health?.worker;const online=cams.filter(camera=>camera.status==='online').length;const pendingEvents=events.filter(event=>telegramReviewStatus(event)==='pending');const criticalEvents=events.filter(event=>event.severity==='critical');
 const action=async(key:string,work:()=>Promise<unknown>,success:string):Promise<boolean>=>{if(busy)return false;setBusy(key);setError('');try{await work();telegramHaptic('success');notify(success,'ok');await load();return true}catch(e){const message=e instanceof Error?e.message:'Действие не выполнено';telegramHaptic('error');setError(message);notify('Не удалось выполнить действие','error');return false}finally{setBusy('')}};
 const openEvents=(filter:TelegramEventFilter)=>{setEventFilter(filter);setSelectionMode(false);setSelectedEventIds([]);setView('События');telegramHaptic()};
 const toggleEventSelection=(id:number)=>setSelectedEventIds(ids=>ids.includes(id)?ids.filter(value=>value!==id):[...ids,id]);
 const acknowledge=(event:Event)=>void action(`ack:${event.id}`,()=>api(`/api/events/${event.id}/ack`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({note:'Проверено из Telegram Mini App'})}),'Событие принято').then(done=>{if(done)setSelectedEvent(current=>current?.id===event.id?{...current,acknowledged:1,review_status:'accepted'}:current)});
 const reject=(event:Event)=>void telegramConfirm('Отметить событие как не принятое?').then(confirmed=>{if(!confirmed)return;void action(`reject:${event.id}`,()=>api(`/api/events/${event.id}/reject`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({note:'Не принято из Telegram Mini App'})}),'Событие отклонено').then(done=>{if(done)setSelectedEvent(current=>current?.id===event.id?{...current,acknowledged:1,review_status:'rejected'}:current)})});
 const reviewSelected=async(review:'accepted'|'rejected')=>{if(!selectedEventIds.length)return;const label=review==='accepted'?'принять':'отклонить';if(!await telegramConfirm(`${label[0].toUpperCase()}${label.slice(1)} ${selectedEventIds.length} выбранных событий?`))return;const endpoint=review==='accepted'?'ack-bulk':'reject-bulk';const done=await action(`bulk:${review}`,()=>api(`/api/events/${endpoint}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event_ids:selectedEventIds,note:review==='accepted'?'Проверено из Telegram Mini App':'Не принято из Telegram Mini App'})}),review==='accepted'?'События приняты':'События отклонены');if(done){setSelectedEventIds([]);setSelectionMode(false)}};
 const requestRestart=async(camera:Cam)=>{if(!await telegramConfirm(`Перезапустить поток «${camera.name}»?`))return;const done=await action(`restart:${camera.id}`,()=>api(`/api/cameras/${camera.id}/restart`,{method:'POST'}),'Поток перезапускается');if(done)setSelectedCamera(current=>current?.id===camera.id?{...current,status:'connecting',fps:0,latency_ms:0}:current)};
 const toggleCamera=async(camera:Cam)=>{const next=Number(camera.enabled)?'отключить аналитику':'включить аналитику';if(!await telegramConfirm(`${next[0].toUpperCase()}${next.slice(1)} камеры «${camera.name}»?`))return;const done=await action(`toggle:${camera.id}`,()=>api(`/api/cameras/${camera.id}/toggle`,{method:'PATCH'}),Number(camera.enabled)?'Аналитика камеры отключена':'Аналитика камеры включена');if(done)setSelectedCamera(current=>current?.id===camera.id?{...current,enabled:current.enabled?0:1,status:'connecting',fps:0,latency_ms:0}:current)};
 const diagnoseCamera=async(camera:Cam)=>{if(busy)return;setBusy(`diagnose:${camera.id}`);setError('');try{const result=await api<CameraDiagnostic>(`/api/cameras/${camera.id}/diagnostics`,{method:'POST'});setDiagnostics(current=>({...current,[camera.id]:result}));telegramHaptic(result.reachable?'success':'warning');notify(result.reachable?'Камера доступна по сети':'Камера не отвечает','warn')}catch(e){setError(e instanceof Error?e.message:'Диагностика недоступна');telegramHaptic('error')}finally{setBusy('')}};
 const activateModel=async(model:Model,test=false)=>{if(!test&&!await telegramConfirm(`Включить «${model.name}» в production-режиме?`))return;void action(`model:${model.name}:${test?'test':'prod'}`,()=>api(`/api/models/${encodeURIComponent(model.name)}/${test?'activate-test':'activate'}`,{method:'POST'}),test?'Тест модели запущен':'Модель включена')};
 const deactivateTest=(model:Model)=>void telegramConfirm(`Остановить тест «${model.name}»?`).then(confirmed=>{if(confirmed)void action(`stop-test:${model.name}`,()=>api(`/api/models/${encodeURIComponent(model.name)}/deactivate-test`,{method:'POST'}),'Тест модели остановлен')});
 const runtimeLabel=(model:Model)=>{const runtime=model.runtime;if(!runtime)return '';if(runtime.status==='ready')return 'Worker загрузил модель';if(runtime.status==='loading')return 'Worker загружает…';if(runtime.status==='error')return runtime.detail||'Ошибка worker';if(runtime.status==='worker_offline')return 'Worker offline';return runtime.detail||'Ожидание worker'};
 const shareShift=()=>{const text=`ZMK Vision · сводка смены\nКамеры онлайн: ${online}/${d?.cameras.total??0}\nСобытия за 24 ч: ${d?.events24h??0}\nКритические: ${d?.critical_unacked??0}\nОжидают решения: ${pendingEvents.length}`;const url=`https://t.me/share/url?url=${encodeURIComponent(location.href)}&text=${encodeURIComponent(text)}`;const tg=(window as any).Telegram?.WebApp;try{if(tg?.openTelegramLink)tg.openTelegramLink(url);else window.open(url,'_blank','noopener');telegramHaptic();notify('Открываю отправку сводки','ok')}catch{notify('Не удалось открыть отправку','error')}};
 const filteredEvents=events.filter(event=>eventFilter==='all'||eventFilter==='critical'&&event.severity==='critical'||eventFilter==='pending'&&telegramReviewStatus(event)==='pending'||eventFilter==='accepted'&&telegramReviewStatus(event)==='accepted'||eventFilter==='rejected'&&telegramReviewStatus(event)==='rejected');
 const filteredCameras=cams.filter(camera=>cameraFilter==='all'||cameraFilter==='online'&&camera.status==='online'||cameraFilter==='attention'&&(camera.status!=='online'||!camera.enabled||camera.telemetry_stale));
 const reviewTotal=analytics?.review.reduce((sum,item)=>sum+item.value,0)||0;const resolvedTotal=(analytics?.totals.accepted||0)+(analytics?.totals.rejected||0);const resolvedRate=reviewTotal?Math.round(resolvedTotal/reviewTotal*100):0;const selectedDiagnostic=selectedCamera?diagnostics[selectedCamera.id]:null;
 if(!d)return <div className="tg-loader tgapp-dark">{error?<div className="api-error"><AlertTriangle/><span><b>Нет связи с API</b><small>{error}</small></span><button onClick={()=>void load()}>Повторить</button></div>:<div className="loader"/>}</div>;
 return <div className="tgapp tgapp-full tgapp-dark"><div className="tghead"><div className="brandmark"><Eye size={21}/></div><span><b>ZMK Vision</b><small>{session?.telegram?`Telegram · ${role}`:'Control Center'} · обновление 12 сек</small></span><button type="button" onClick={()=>void load()} aria-label="Обновить"><RefreshCw size={17} className={loading?'spin':''}/></button></div>{toast&&<div className={`tg-toast ${toast.tone}`} role="status"><span>{toast.tone==='ok'?<Check size={14}/>:<AlertTriangle size={14}/>}</span>{toast.message}</div>}{error&&<div className="tg-inline-error"><AlertTriangle size={15}/><span>{error}</span><button type="button" onClick={()=>setError('')}><X size={14}/></button></div>}
 {view==='Главная'&&<><section className="tg-command-hero"><span>ОПЕРАТИВНЫЙ КОНТУР</span><h2>{d.critical_unacked?`${d.critical_unacked} критических требуют внимания`:'Смена под контролем'}</h2><p>{worker?.connected?`${online} камер передают телеметрию, worker на связи.`:'Нет подтверждённого heartbeat от inference-worker.'}</p><div><button type="button" onClick={()=>openEvents('critical')}><AlertTriangle size={14}/>Критические</button><button type="button" onClick={()=>openEvents('pending')}><Clock3 size={14}/>В очереди {pendingEvents.length}</button></div></section><div className={`tgstate ${worker?.connected?'ok':'warn'}`}><span className={worker?.connected?'pulse':'tg-warn-dot'}/><div><b>{worker?.connected?'Система на связи':'Нужна проверка worker'}</b><small>{online}/{d.cameras.total} камер онлайн · {worker?.detail||'Heartbeat ожидается'}</small></div></div><div className="tgmetrics"><div><Camera/><span><b>{online}/{d.cameras.total}</b><small>Камеры</small></span></div><div><ShieldAlert/><span><b>{d.events24h}</b><small>События / 24 ч</small></span></div><div><AlertTriangle/><span><b>{d.critical_unacked}</b><small>Критические</small></span></div><div><Cpu/><span><b>{d.gpu_load===null?'—':`${d.gpu_load}%`}</b><small>GPU</small></span></div></div><section className="tgsection tg-home-trend-card"><div className="tgsection-head"><div><h3>Пульс событий</h3><small>Последние 12 часов · реальные детекции</small></div><button type="button" onClick={()=>setView('Аналитика')}>Графики</button></div><TelegramTrend compact data={d.trend}/><div className="tg-home-trend-meta"><span><b>{Math.round((d.precision||0))}%</b><small>precision модели</small></span><span><b>{d.avg_latency_ms} мс</b><small>средняя задержка</small></span><span><b>{pendingEvents.length}</b><small>ожидают решения</small></span></div></section><section className="tg-overview-card"><span>АКТИВНАЯ МОДЕЛЬ</span><b>{activeModel?.name||'Не выбрана'}</b><small>{activeModel?.test_mode?'Тест на камере':activeModel?.runtime?runtimeLabel(activeModel):'Выберите модель в разделе «Модели»'}</small></section><section className="tg-quick-grid"><button type="button" onClick={()=>openEvents('pending')}><span><Clock3 size={16}/></span><b>Разобрать очередь</b><small>{pendingEvents.length} событий ждут решения</small></button><button type="button" onClick={()=>setView('Аналитика')}><span><BarChart3 size={16}/></span><b>Аналитика</b><small>Тренды, типы и зоны риска</small></button><button type="button" onClick={shareShift}><span><Upload size={16}/></span><b>Сводка смены</b><small>Поделиться в Telegram</small></button><button type="button" onClick={()=>setView('Камеры')}><span><Radio size={16}/></span><b>Живые камеры</b><small>{online} из {cams.length} на связи</small></button></section><section className="tgsection"><div className="tgsection-head"><h3>Последние события</h3><button type="button" onClick={()=>openEvents('all')}>Все</button></div>{events.length?events.slice(0,5).map(event=><button className="tgevent" key={event.id} onClick={()=>setSelectedEvent(event)}><i className={`sev ${event.severity}`}/><span><b>{labels[event.type]||event.type}</b><small>{event.camera_name} · {Math.round(event.confidence*100)}% · {telegramReviewStatus(event)==='pending'?'ожидает':'проверено'}</small></span><time>{new Date(event.timestamp).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</time></button>):<div className="tg-empty">Событий за период пока нет.</div>}</section></>}
 {view==='Аналитика'&&<><section className="tg-analytics-hero"><div><span>ИНФОГРАФИКА СМЕНЫ</span><h2>{analytics?.totals.events||0} событий за {analyticsHours===24?'24 часа':analyticsHours===168?'7 дней':'30 дней'}</h2><p>Данные строятся на реальном журнале детекций и обновляются автоматически.</p></div><BarChart3 size={28}/></section><div className="tg-periods">{([{hours:24,label:'24 ч'},{hours:168,label:'7 дней'},{hours:720,label:'30 дней'}] as const).map(item=><button type="button" key={item.hours} className={analyticsHours===item.hours?'active':''} aria-pressed={analyticsHours===item.hours} onClick={()=>setAnalyticsHours(item.hours)}>{item.label}</button>)}</div>{analytics?<><div className="tg-analytics-kpis"><span><b>{analytics.totals.critical}</b><small>критические</small></span><span><b>{analytics.totals.pending}</b><small>в очереди</small></span><span><b>{Math.round(analytics.totals.avg_confidence*100)}%</b><small>уверенность</small></span><span><b>{resolvedRate}%</b><small>разобрано</small></span></div><section className="tgsection tg-analytics-card"><div className="tgsection-head"><div><h3>Динамика событий</h3><small>{analytics.bucket==='hour'?'По часам':'По дням'} · {analytics.totals.events} всего</small></div>{canReport&&<button type="button" onClick={()=>downloadFile(`/api/reports/analytics.csv?hours=${analyticsHours}&bucket=auto`,'zmk-analytics.csv')}><Download size={13}/></button>}</div><TelegramTrend data={analytics.buckets.map(item=>({label:item.label,value:item.total}))}/><div className="tg-chart-foot"><span><i className="critical"/>критические: <b>{analytics.totals.critical}</b></span><span><i className="pending"/>в очереди: <b>{analytics.totals.pending}</b></span></div></section><div className="tg-analytics-split"><section className="tgsection tg-analytics-card"><h3>Решения оператора</h3><TelegramDonut items={analytics.review} label="событий" value={reviewTotal}/></section><section className="tgsection tg-analytics-card"><h3>Критичность</h3><TelegramBars items={analytics.severity}/></section></div><section className="tgsection tg-analytics-card"><div className="tgsection-head"><div><h3>Типы нарушений</h3><small>Что встречается чаще всего</small></div><button type="button" onClick={()=>openEvents('pending')}>Очередь</button></div><TelegramBars items={analytics.types}/></section><section className="tgsection tg-analytics-card"><div className="tgsection-head"><div><h3>Зоны внимания</h3><small>Камеры с наибольшим числом событий</small></div><button type="button" onClick={()=>setView('Камеры')}>Камеры</button></div>{analytics.cameras.length?<div className="tg-camera-ranking">{analytics.cameras.slice(0,6).map((camera,index)=><button type="button" key={camera.camera_id} onClick={()=>{const target=cams.find(item=>item.id===camera.camera_id);if(target)setSelectedCamera(target)}}><em>{index+1}</em><span><b>{camera.name}</b><small>{camera.zone} · {camera.pending} в очереди</small></span><strong>{camera.total}</strong>{camera.critical>0&&<i>{camera.critical}!</i>}</button>)}</div>:<div className="tg-empty">Данных по камерам пока нет.</div>}</section><button className="tg-share-report" type="button" onClick={shareShift}><Upload size={16}/><span><b>Отправить сводку смены</b><small>Камеры, критические и очередь проверки</small></span><ChevronRight size={16}/></button></>:<div className="tg-loader-inline"><div className="loader"/></div>}</>}
 {view==='Камеры'&&<section className="tgsection tg-camera-section"><div className="tgsection-head"><div><h3>Камеры</h3><small>Последние реальные кадры от inference-worker</small></div><button type="button" onClick={()=>void load()}>Обновить</button></div><div className="tg-filter-row">{([{id:'all',label:`Все ${cams.length}`},{id:'online',label:`Онлайн ${online}`},{id:'attention',label:`Внимание ${cams.length-online}`} ] as {id:TelegramCameraFilter,label:string}[]).map(item=><button type="button" key={item.id} className={cameraFilter===item.id?'active':''} onClick={()=>setCameraFilter(item.id)}>{item.label}</button>)}</div>{!filteredCameras.length?<div className="tg-empty">В этой группе камер нет.</div>:<div className="tg-camera-grid">{filteredCameras.map(camera=><button type="button" className={`tg-camera-card ${camera.status}`} key={camera.id} onClick={()=>setSelectedCamera(camera)}><div className="tg-camera-image"><TelegramImage url={`/api/cameras/${camera.id}/snapshot`} alt={`Камера ${camera.name}`} refreshSeconds={8}/><em>{camera.status==='online'?'● LIVE':STATUS_LABEL[camera.status]||camera.status}</em></div><span><b>{camera.name}</b><small>{camera.zone} · {camera.fps.toFixed(1)} FPS</small><i>{camera.enabled?`${camera.latency_ms||'—'} мс · ${telegramAge(camera.snapshot_age_seconds)}`:'Аналитика отключена'}</i></span></button>)}</div>}</section>}
 {view==='События'&&<section className="tgsection tg-events-section"><div className="tgsection-head"><div><h3>События</h3><small>Фильтруйте, открывайте кадр, подтверждайте или отклоняйте</small></div>{canOperate&&<button type="button" onClick={()=>{setSelectionMode(current=>!current);setSelectedEventIds([])}}>{selectionMode?'Готово':'Выбрать'}</button>}</div><div className="tg-filter-row tg-event-filters">{([{id:'all',label:`Все ${events.length}`},{id:'pending',label:`Очередь ${pendingEvents.length}`},{id:'critical',label:`Крит. ${criticalEvents.length}`},{id:'accepted',label:'Приняты'},{id:'rejected',label:'Не приняты'}] as {id:TelegramEventFilter,label:string}[]).map(item=><button type="button" key={item.id} className={eventFilter===item.id?'active':''} onClick={()=>{setEventFilter(item.id);setSelectedEventIds([])}}>{item.label}</button>)}</div>{selectionMode&&<div className="tg-bulk-review"><span><b>{selectedEventIds.length}</b><small>выбрано</small></span><button type="button" disabled={!selectedEventIds.length||busy==='bulk:accepted'} onClick={()=>void reviewSelected('accepted')}><Check size={14}/>Принять</button><button type="button" className="reject" disabled={!selectedEventIds.length||busy==='bulk:rejected'} onClick={()=>void reviewSelected('rejected')}><X size={14}/>Отклонить</button></div>}{!filteredEvents.length?<div className="tg-empty">Событий по выбранному фильтру нет.</div>:filteredEvents.map(event=>{const review=telegramReviewStatus(event);const pending=review==='pending';const selected=selectedEventIds.includes(event.id);return <div className={`tg-event-card ${selected?'selected':''}`} key={event.id}>{selectionMode&&<button type="button" className={`tg-event-select ${selected?'selected':''}`} aria-label="Выбрать событие" onClick={()=>toggleEventSelection(event.id)}>{selected?<Check size={13}/>:null}</button>}<button type="button" className="tg-event-open" onClick={()=>setSelectedEvent(event)}><i className={`sev ${event.severity}`}/><span><b>{labels[event.type]||event.type}</b><small>{event.camera_name} · {Math.round(event.confidence*100)}% · {new Date(event.timestamp).toLocaleString('ru-RU')}</small><em className={review}>{review==='pending'?'ожидает решения':review==='accepted'?'принято':'не принято'}</em></span><ChevronRight size={16}/></button>{canOperate&&pending&&!selectionMode&&<div className="tg-event-review-actions"><button type="button" className="tg-ack" disabled={busy===`ack:${event.id}`} onClick={()=>acknowledge(event)}><Check size={14}/>{busy===`ack:${event.id}`?'…':'Принять'}</button><button type="button" className="tg-reject" disabled={busy===`reject:${event.id}`} onClick={()=>reject(event)}><X size={14}/></button></div>}</div>})}</section>}
 {view==='Модели'&&<section className="tgsection tg-models-section"><div className="tgsection-head"><div><h3>Модели</h3><small>Управление загрузкой и безопасными тестами</small></div><button type="button" onClick={()=>void load()}>Обновить</button></div><div className="tg-model-summary"><span><b>{models.filter(model=>model.status==='ready').length}</b><small>готово</small></span><span><b>{activeModel?1:0}</b><small>активна</small></span><span><b>{models.filter(model=>model.test_mode).length}</b><small>тест</small></span></div>{models.length===0?<div className="tg-empty">Модели не зарегистрированы.</div>:<div className="tg-model-list">{models.map(model=>{const valid=model.precision!==null&&model.recall!==null;return <article className={`tg-model-card ${model.active?'active':''}`} key={model.name}><div><span>{model.active?(model.test_mode?'ТЕСТ':'АКТИВНА'):'ГОТОВА'}</span><b>{model.name}</b><small>{model.format} · P {model.precision??'—'} / R {model.recall??'—'}</small>{valid&&<div className="tg-model-quality"><i><em style={{width:`${Math.min(100,model.precision||0)}%`}}/></i><i><em style={{width:`${Math.min(100,model.recall||0)}%`}}/></i></div>}{model.active&&<em className={model.runtime?.status||''}>{runtimeLabel(model)}</em>}</div>{canAdmin&&!model.active&&<div className="tg-model-actions"><button type="button" disabled={busy===`model:${model.name}:test`} onClick={()=>void activateModel(model,true)}><Eye size={14}/>Тест</button>{valid&&<button type="button" className="production" disabled={busy===`model:${model.name}:prod`} onClick={()=>void activateModel(model)}><Play size={14}/>Включить</button>}</div>}{canAdmin&&model.active&&model.test_mode&&<div className="tg-model-actions"><button type="button" className="stop" disabled={busy===`stop-test:${model.name}`} onClick={()=>deactivateTest(model)}><X size={14}/>Стоп</button></div>}</article>})}</div>}</section>}
 {view==='Ещё'&&<section className="tgsection tg-more-section"><section className="tg-mobile-profile"><div className="avatar">{session?.user?.name?.slice(0,1).toUpperCase()||'Z'}</div><span><b>{session?.user?.name||'Оператор ZMK Vision'}</b><small>Роль: {role} · защищённая Telegram-сессия</small></span><i className={worker?.connected?'online':'offline'}/></section><div className="tgsection-head"><div><h3>Система и отчёты</h3><small>Фактические показатели хоста и сервисов</small></div><button type="button" onClick={()=>void load()}>Обновить</button></div><div className="tg-gauges"><TelegramGauge label="CPU" value={health?.cpu} tone="blue"/><TelegramGauge label="RAM" value={health?.ram} tone="green"/><TelegramGauge label="Диск" value={health?.disk} tone="amber"/><TelegramGauge label="GPU" value={health?.gpu} tone="red"/></div><div className="tg-service-list">{(health?.services||[]).map(service=><span key={service.name}><i className={service.status}/><b>{service.name}</b><small>{service.status}</small></span>)}</div><div className="tg-report-actions"><button className="tgaction" type="button" onClick={shareShift}><Upload/><span><b>Сводка смены</b><small>Поделиться через Telegram</small></span><ChevronRight/></button>{canReport&&<><button className="tgaction" type="button" onClick={()=>downloadFile(`/api/reports/analytics.csv?hours=${analyticsHours}&bucket=auto`,'zmk-analytics.csv')}><BarChart3/><span><b>Аналитика CSV</b><small>Выбранный период: {analyticsHours===24?'24 ч':analyticsHours===168?'7 дней':'30 дней'}</small></span><Download/></button><button className="tgaction" type="button" onClick={()=>downloadFile('/api/reports/events.zip','zmk-events-with-evidence.zip')}><Camera/><span><b>События + кадры</b><small>ZIP: русская таблица, HTML-отчёт и кадры нарушений</small></span><Download/></button><button className="tgaction" type="button" onClick={()=>downloadFile('/api/reports/errors.csv?hours=24','zmk-errors.csv')}><FileWarning/><span><b>Ошибки CSV</b><small>WARNING / ERROR / CRITICAL</small></span><ChevronRight/></button><button className="tgaction" type="button" onClick={()=>downloadFile('/api/reports/support.zip?hours=24','zmk-support-bundle.zip')}><Stethoscope/><span><b>Пакет диагностики</b><small>Без секретов: ресурсы, камеры, аналитика и сводка ошибок</small></span><Download/></button></>}</div><div className="tg-more-tip"><Bell size={15}/><span><b>Оперативный режим</b><small>Статус, графики и очередь решений обновляются каждые 12 секунд. Кадры камер — каждые 8 секунд.</small></span></div></section>}
 <div className="tgnav">{[['Главная',LayoutDashboard],['Аналитика',BarChart3],['Камеры',Camera],['События',ShieldAlert],['Модели',Cpu],['Ещё',Settings]].map(([name,Icon]:any)=><button key={name} className={view===name?'active':''} onClick={()=>{setView(name);telegramHaptic()}}><Icon size={17}/><span>{name}</span></button>)}</div>
 {selectedCamera&&<div className="tg-sheet-backdrop" onClick={()=>setSelectedCamera(null)}><div className="tg-sheet" onClick={event=>event.stopPropagation()}><div className="tg-sheet-head"><div><span>КАМЕРА</span><h3>{selectedCamera.name}</h3><small>{selectedCamera.zone} · {selectedCamera.id}</small></div><button type="button" onClick={()=>setSelectedCamera(null)}><X size={18}/></button></div><div className="tg-sheet-image"><TelegramImage url={`/api/cameras/${selectedCamera.id}/snapshot`} alt={`Камера ${selectedCamera.name}`} refreshSeconds={6}/></div><div className="tg-sheet-meta"><span><b>{STATUS_LABEL[selectedCamera.status]||selectedCamera.status}</b><small>Статус</small></span><span><b>{selectedCamera.fps.toFixed(1)} FPS</b><small>Поток</small></span><span><b>{selectedCamera.latency_ms||'—'} мс</b><small>Задержка</small></span></div><div className="tg-camera-sheet-note"><Radio size={14}/><span>Кадр: <b>{telegramAge(selectedCamera.snapshot_age_seconds)}</b> · аналитика {selectedCamera.enabled?'включена':'отключена'}</span></div>{selectedCamera.last_error&&<div className="tg-sheet-error">{selectedCamera.last_error}</div>}{selectedDiagnostic&&<div className={`tg-diagnostic ${selectedDiagnostic.reachable?'ok':'error'}`}><i className={selectedDiagnostic.reachable?'healthy':'error'}/><span><b>{selectedDiagnostic.reachable?'TCP-доступ подтверждён':'Проверка сети не пройдена'}</b><small>{selectedDiagnostic.reachable?`${selectedDiagnostic.latency_ms} мс · ${selectedDiagnostic.message}`:selectedDiagnostic.message||selectedDiagnostic.last_error||'Нет ответа камеры'}</small></span></div>}<div className="tg-sheet-actions">{canOperate&&<button type="button" className="secondary" disabled={busy===`diagnose:${selectedCamera.id}`} onClick={()=>void diagnoseCamera(selectedCamera)}><Stethoscope size={15}/>{busy===`diagnose:${selectedCamera.id}`?'Проверяю…':'Диагностика'}</button>}{canAdmin&&<button type="button" className="secondary" disabled={busy===`toggle:${selectedCamera.id}`} onClick={()=>void toggleCamera(selectedCamera)}><Radio size={15}/>{selectedCamera.enabled?'Отключить':'Включить'}</button>}{canAdmin&&selectedCamera.enabled?<button type="button" className="tg-sheet-primary" disabled={busy===`restart:${selectedCamera.id}`} onClick={()=>void requestRestart(selectedCamera)}><RefreshCw size={15}/>{busy===`restart:${selectedCamera.id}`?'Перезапускаю…':'Перезапустить поток'}</button>:null}</div></div></div>}
 {selectedEvent&&<div className="tg-sheet-backdrop" onClick={()=>setSelectedEvent(null)}><div className="tg-sheet" onClick={event=>event.stopPropagation()}><div className="tg-sheet-head"><div><span>СОБЫТИЕ</span><h3>{labels[selectedEvent.type]||selectedEvent.type}</h3><small>{selectedEvent.camera_name} · {new Date(selectedEvent.timestamp).toLocaleString('ru-RU')}</small></div><button type="button" onClick={()=>setSelectedEvent(null)}><X size={18}/></button></div>{selectedEvent.has_frame?<div className="tg-sheet-image"><TelegramImage url={`/api/events/${selectedEvent.id}/frame`} alt="Кадр события"/></div>:<div className="tg-image-empty"><ShieldAlert size={20}/><span>Кадр события не сохранён</span></div>}<div className="tg-sheet-meta"><span><b>{Math.round(selectedEvent.confidence*100)}%</b><small>Уверенность</small></span><span><b>{selectedEvent.severity}</b><small>Критичность</small></span><span><b>{telegramReviewStatus(selectedEvent)==='accepted'?'Принято':telegramReviewStatus(selectedEvent)==='rejected'?'Не принято':'Ожидает'}</b><small>Решение</small></span></div>{selectedEvent.note&&<div className="tg-event-note"><Check size={13}/><span>{selectedEvent.note}</span></div>}<div className="tg-sheet-actions"><button type="button" className="secondary" onClick={()=>{const camera=cams.find(item=>item.id===selectedEvent.camera_id);if(camera){setSelectedEvent(null);setSelectedCamera(camera)}}}><Camera size={15}/>Открыть камеру</button>{canOperate&&telegramReviewStatus(selectedEvent)==='pending'&&<><button type="button" className="secondary reject" disabled={busy===`reject:${selectedEvent.id}`} onClick={()=>reject(selectedEvent)}><X size={15}/>Не принять</button><button type="button" className="tg-sheet-primary" disabled={busy===`ack:${selectedEvent.id}`} onClick={()=>acknowledge(selectedEvent)}><Check size={15}/>{busy===`ack:${selectedEvent.id}`?'Сохраняю…':'Принять событие'}</button></>}</div></div></div>}
 </div>}

